from itertools import product


def _route(data, coupon_rule, minimum_duration, inclusive_deadline):
    required = data.get("required", [])
    required_bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source, target = data["source"], data["target"]
    initial_mask = required_bit.get(source, 0)
    start = data["start"]
    limit = data["deadline"]
    coupons = data["coupons"]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    # State includes coupon usage and required visits: neither is node-local.
    initial = (source, 0, initial_mask)
    best = {initial: start}
    queue = [(start, source, 0, initial_mask)]
    while queue:
        time, node, used, mask = heapq.heappop(queue)
        state = (node, used, mask)
        if best.get(state) != time:
            continue
        if node == target and mask == full and (coupon_rule != "exact" or used == coupons):
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            next_node = edge["v"]
            next_mask = mask | required_bit.get(next_node, 0)
            durations = [(edge["duration"], used)]
            if used < coupons:
                duration = max(minimum_duration,
                               edge["duration"] - edge.get("discount", 0))
                durations.append((duration, used + 1))
            for duration, next_used in durations:
                arrival = depart + duration
                if arrival > limit if inclusive_deadline else arrival >= limit:
                    continue
                next_state = (next_node, next_used, next_mask)
                if arrival < best.get(next_state, float("inf")):
                    best[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_used, next_mask))
    return {"arrival": None}


def _build_route(coupon_rule, minimum_duration):
    def solve(data):
        return _route(data, coupon_rule, minimum_duration, True)
    return solve


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(numerator):
        return ((numerator + 5000) // 10000 if mode == "half_up"
                else numerator // 10000)

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(net * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]

    options = {}
    for name in names:
        versions = [row["version"] for row in packages[name]
                    if row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
        options[name] = [-1] + versions

    best_vector = None
    best_result = None
    for vector in product(*(options[name] for name in names)):
        assignment = dict(zip(names, vector))
        if any(assignment.get(name, -1) < 0 or
               not bounds[0] <= assignment[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue

        installed = {name for name in names if assignment[name] >= 0}
        rows = {name: next(row for row in packages[name]
                           if row["version"] == assignment[name])
                for name in installed}
        graph = {name: [] for name in installed}
        valid = True
        for name, row in rows.items():
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                version = assignment.get(target, -1)
                if version < 0 or not dep["min"] <= version <= dep["max"]:
                    valid = False
                    break
                graph[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        # Require exactly the roots' active closure, not arbitrary extra installs.
        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            if name not in installed:
                valid = False
                break
            reachable.add(name)
            stack.extend(graph[name])
        if not valid or reachable != installed:
            continue

        active, finished = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in graph[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(visit(name) for name in installed):
            continue

        if best_vector is None or vector > best_vector:
            best_vector = vector
            best_result = {name: assignment[name] for name in names
                           if assignment[name] >= 0}

    if best_result is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_result}


def _intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    eligible = [job for job in jobs if job["id"] not in blocked]
    if not mandatory.issubset({job["id"] for job in eligible}):
        return {"error": "impossible"}

    best_value = None
    best_ids = None
    for chosen in _subsets(eligible, k):
        ids = tuple(sorted(job["id"] for job in chosen))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in chosen:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        active_ends = []
        feasible = True
        for job in sorted(chosen, key=lambda item: (item["start"], item["end"])):
            active_ends = [end for end in active_ends if end > job["start"]]
            if len(active_ends) >= 2:
                feasible = False
                break
            active_ends.append(job["end"])
        if not feasible:
            continue

        value = sum(job["value"] for job in chosen)
        if (best_value is None or value > best_value or
                (value == best_value and ids > best_ids)):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _subsets(items, size):
    # Small bounded input; enumerate combinations without third-party modules.
    def generate(start, picked):
        if len(picked) == size:
            yield picked
            return
        need = size - len(picked)
        for i in range(start, len(items) - need + 1):
            yield from generate(i + 1, picked + [items[i]])
    if size < 0 or size > len(items):
        return
    yield from generate(0, [])


